fun main(){var n=0;fun ck(v:Boolean){check(v);n++}
val id="12345678-1234-1234-1234-123456789abc";ck(Batch21.validId(id));ck(!Batch21.validId("../bad"));ck(Batch21.url("release",id)=="https://musicbrainz.org/release/$id");ck(runCatching{Batch21.url("bad",id)}.isFailure);ck(Batch21.quoted("A\"B")=="\"A\\\"B\"");ck(Batch21.search("release-group","test")=="releasegroup:\"test\"");ck(Batch21.search("recording","foo") == "recording:\"foo\"");ck(runCatching{Batch21.search("recording","  ")}.isFailure);val today=LocalDate.parse("2026-11-25");ck(Batch21.recent("A",today).contains("firstreleasedate:[2026-10-26 TO 2026-11-25]"));ck(Batch21.isRecent("2026-10-26",today));ck(Batch21.isRecent("2026-11-25",today));ck(!Batch21.isRecent("2026-10-25",today));ck(!Batch21.isRecent("2026-11-26",today));ck(!Batch21.isRecent("2026-11",today));ck(Batch21.contact("maintainer@example.org")!=null);ck(Batch21.contact("no email")==null);ck(Batch21.contact("a@x.org\nOther: yes")==null);ck(Batch21.limit(999)==50);ck(Batch21.limit(0)==1);ck(Batch21.artistTypes("EP"));ck(!Batch21.artistTypes("broadcast"));ck(Batch21.distinctValid(listOf(id,id.uppercase(),"bad"),{it})==listOf(id));ck(Batch21.text("a\nb\u0000c")=="abc");ck(Batch21.animationContainer("GIF89a123456".toByteArray()));ck(Batch21.animationContainer("RIFF1234WEBP".toByteArray()));ck(!Batch21.animationContainer("RIFF1234WAVE".toByteArray()));ck(!Batch21.animationContainer("GIF89a".toByteArray()));ck(Batch21.recent("",today).startsWith("(primarytype:"));ck(Batch21.fraction(75f,100)==.75f);ck(Batch21.fraction(-5f,100)==0f);ck(Batch21.fraction(200f,100)==1f);ck(Batch21.fraction(Float.NaN,100)==null);ck(Batch21.fraction(0f,0)==null);ck(Batch21.dragged(20f,40f,10));ck(!Batch21.dragged(20f,25f,10));println("$n V21 assertions passed")}
